// 진짜 오류만 보낸다 (2026-10-07, docs/raw/n8nErrorTrigger/Error Trigger.json 의 개선판)
//
// 1) '가져올 것이 없다' 계열은 오류가 아니라 정상 결과다 — 보내지 않는다.
//    실제로 받은 메시지 문구를 보고 BENIGN 목록을 늘린다.
// 2) 오류 본문에 HTML 이 섞이면(504 쪽 등) 태그를 걷고 300자로 자른다.
//    parse_mode 를 쓰지 않는 이유도 같다 — < & 가 섞이면 텔레그램이 메시지를 버린다.
const BENIGN = [
  /no (items|data|results|records|rows)( found| returned)?/i,
  /nothing to (fetch|process|do)/i,
  /returned no (items|data)/i,
  /empty (response|result|array)/i,
  /가져올.*없/,
  /새로운? .*없습니다/,
  /조회 결과가? 없/,
];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const e = (j.execution && j.execution.error) || {};
  const raw = [e.message, e.description].filter(Boolean).join(' / ');
  if (BENIGN.some((re) => re.test(raw))) continue;
  const summary = raw.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300) || '(오류 문구 없음)';
  out.push({ json: { ...j, summary, lastNode: (j.execution && j.execution.lastNodeExecuted) || '-', url: (j.execution && j.execution.url) || '' } });
}
return out;
